(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.4)*22 + Math.cos(y*0.022-t*0.3)*16;
  const w1y = Math.cos(y*0.02-t*0.35)*22 + Math.sin(x*0.025+t*0.45)*16;
  const w2x = Math.sin((x+y)*0.012+t*0.25)*14 + Math.cos((x-y)*0.015-t*0.2)*11;
  const w2y = Math.cos((x-y)*0.013-t*0.3)*14 + Math.sin((x+y)*0.016+t*0.35)*11;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const wells = [
    [160+Math.sin(t*0.5)*120,80+Math.cos(t*0.35)*60,0.9,0.08,1.8],
    [320+Math.cos(t*0.45)*110,160+Math.sin(t*0.6)*70,1.1,0.09,2.0],
    [240+Math.sin(t*0.3+2)*150,120+Math.cos(t*0.45+1)*100,0.7,0.07,2.3],
    [100+Math.cos(t*0.7+1)*90,180+Math.sin(t*0.55+3)*70,1.3,0.1,1.5],
    [380+Math.sin(t*0.4+4)*100,50+Math.cos(t*0.8+2)*80,0.8,0.075,2.5],
    [240+Math.cos(t*0.3+5)*130,210+Math.sin(t*0.5)*90,1.0,0.085,1.9],
    [60+Math.sin(t*0.6+3)*70,40+Math.cos(t*0.4+4)*50,1.2,0.095,1.6],
    [420+Math.cos(t*0.5+2)*60,220+Math.sin(t*0.7+1)*50,0.85,0.07,2.2]
  ];
  let act=0,inh=0,grav=0,cross=0;
  for(let a=0;a<wells.length;a++){
    const [wX,wY,mass,f,sp]=wells[a];
    const d=Math.sqrt((sx-wX)**2+(sy-wY)**2);
    const d2=Math.sqrt((sx-wells[(a+3)%8][0])**2+(sy-wells[(a+3)%8][1])**2);
    act+=Math.sin(d*f-t*sp)*mass;
    inh+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*mass;
    grav+=mass/(1+d*0.012);
    cross+=Math.sin((d-d2)*0.04+t*0.8)*mass*0.3;
  }
  const n=wells.length; act/=n; inh/=n; grav/=n; cross/=n;
  const bg1=(Math.sin(sx*0.035+sy*0.028+t*0.9)+Math.sin(sx*0.025-sy*0.038+t*1.2))/2;
  const bg2=Math.sin((sx+sy)*0.11+t*2.8)*0.3+Math.sin((sx-sy)*0.09-t*2.2)*0.3;
  const bg3=Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.07-t*1.3)*0.4;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.8)+Math.sin(dist*0.035+ang*4.5-t*1.4))*0.35;
  const potential=grav*0.35,kinetic=Math.abs(act-inh)*0.55;
  const energy=Math.min((potential+kinetic)*1.2,1.4);
  const wave=Math.sin(sx*0.06-sy*0.04+t*1.6)*Math.cos(sx*0.03+sy*0.05-t*1.2)*0.25;
  const reaction=Math.tanh((act-inh*0.6+bg*0.2+spiral+energy*0.25+cross*0.15+wave)*2.8);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4)*1.8)*0.35;
  const blend=reaction*0.68+cell*0.32, v=blend*0.5+0.5;
  const pal=[[2,2,18],[5,8,45],[8,25,90],[0,90,150],[0,220,190],[120,255,30],[255,200,0],[255,70,60],[220,0,130],[110,0,200],[35,5,100],[2,2,18]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const absR=Math.abs(reaction);
  const glow=absR>0.45?1.0+(absR-0.45)*1.8:1.0;
  const edge=absR>0.72?1.35:1.0;
  const lum=glow*edge;
  const bloom=Math.max(0,energy-0.7)*0.6;
  const neonTint=absR>0.6?Math.sin(t*3)*15:0;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum+bloom*50+neonTint*0.5)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum+bloom*70+neonTint)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum+bloom*90-neonTint*0.3)|0)
  ];
}
